using static StrataLint.Scribe.DefinitionDsl;
using static StrataLint.Scribe.FormulaDsl;
using F = StrataLint.Scribe.FormulaDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Quantum.Algebra;

internal sealed class PBOriginalReadoutRealizationDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Cone-positive functionals and actual finite matrix corners read the whole original directed two-table; a single ambient state also supplies coherent central-sector outer budgets.",
        H("Original labels, positive two-tables, and a selected central sector"),
        Blocks(Describe.Lean(DescribeId.Create("original-positive-readings"),
            DeclarationHandle.Create("D5/S3/Quantum/Algebra/PBOriginalReadoutRealization.original_positive_readings"),
            H("Whole directed tables and actual finite matrix corners"),
            StatementSource.FromAuthor(Disp(PositiveStatement())), AssessedProvenance.FromRepo(),
            Blocks(
                Paragraph(Text("Let C be any subset of the original real normed space E detected exactly by all original real-linear evaluations p. J is the original bilinear Jordan product and D is the same arbitrary total function. Suppose every original directed two-table is positive semidefinite. Every C-positive real-linear functional f then reads the whole directed table positively, for every original pair and every complex test vector. Its determinant gives the stated quadratic budget. No nonzero, unit-mass or continuity premise is imposed on f or the original evaluations. The proof uses the positive quadratic original label and the exact cone, rather than an extension to an ambient associative algebra.")),
                Paragraph(Text("A consequence for the original unit row uses an arbitrary real normed E, which need not be complete, and an arbitrary complete real normed X with raw six-law JB data (JX,uX). Let i:E->X be the same dense real linear isometry, with i(u)=uX and i(J(a,b))=JX(i(a),i(b)). Assume that the actual square cone {a: there exists y in X with JX(y,y)=i(a)} is detected exactly by the unchanged original evaluation family, that this family separates E, and that every actual directed original two-table is positive semidefinite. Retain the same arbitrary total D:E times E->E and full PB: for nu=D(a,b)-J(a,c) and omega=J(a,b)+D(a,c), D(b+nu,c+omega)-D(b-nu,c-omega)=-2(J(b,nu)+J(c,omega)). Then D(s u,b)=0 for every real s whenever i(b) or i(-b) is an actual square in X. All original evaluation masses and zero inputs remain in scope.")),
                Paragraph(Text("For a nonzero h=D(s u,b), the raw JB construction in JBComplexification supplies a positive unital norm-supporting beta on X. Put f=beta composed with i and Z=f(h). The ambient square bound at uX and positive_table_transfer give f(J(h,h))=Z squared and f(J(h-Z u,h-Z u))=0. Applying the same determinant inequality to this null vector shows f(J(h,x))=Z f(x) for every original x. Set k=s Z/(1+s squared), nu=h-sk u and omega=s b. Original P2 and separation give D(s u,k u)=0. The two literal PB outer pairs satisfy (k u+omega)-s(b+nu)=-s(h-Z u) and (k u-omega)+s(b-nu)=-s(h-Z u). Their determinant budgets vanish, so both actual outer D readings vanish. The PB difference yields f(J(b,h))=0, and Z nonzero yields f(b)=0.")),
                Paragraph(Text("For the semidefinite b, choose v=i(b) or i(-b) and a square root y in X with JX(y,y)=v. The ambient upper square bound at y is norm(y) squared uX-v. Applying quadratic_preserves_squares with parameter y gives norm(y) squared v-JX(v,v) as an actual square; the Jordan identity identifies this expression. Positivity and beta(v)=0 force beta(JX(v,v))=0, hence f(J(b,b))=0 in either sign case. The original determinant bound at (s u,b) then forces f(h)=0, contradicting norm support. Every D call stays on E. This argument proves the semidefinite second-input unit row in the stated general JB completion; its general unit row still requires the separate pure-state approximation and subsequent two-generator argument. The finite full-matrix application below has its own evaluation hypotheses and polynomial and spectral derivation. Neither argument extends D to the completion.")),
                new DocumentBlock.Section(H("Finite full-matrix application on unchanged original labels"), Blocks(
                    Paragraph(Text("Fix arbitrary universe-polymorphic types A, E, P and n, with CStarAlgebra A, PartialOrder A, NormedAddCommGroup E, NormedSpace Real E, Fintype n and DecidableEq n. Let O:PBOriginalReadoutRealization.OriginalData (A:=A) (E:=E) P. Write J=O.J, u=O.u and D=O.D. Thus i=O.i is the same real-linear isometric self-adjoint-valued inclusion into A, i(u)=1 and i(J(v,w))=(i(v)i(w)+i(w)i(v))/2. The unchanged preparations p:P->(E->_Real Real) detect exactly C={e:0<=i(e)}, and every original directed table originalTable J D (p preparation) v w is positive semidefinite. E need not be complete, and D:E times E->E remains an arbitrary total function.")),
                    Paragraph(Text("Take q:E->_Real selfAdjoint(Matrix n n Complex), with q(u)=I, q(J(v,w))=(q(v)q(w)+q(w)q(v))/2 for every original v,w, and q(e) positive semidefinite whenever 0<=i(e). Use the L2 operator norm on the full finite self-adjoint matrix target. Assume full PB on the same E: for nu=D(v,w)-J(v,c) and omega=J(v,w)+D(v,c), D(w+nu,c+omega)-D(w-nu,c-omega)=-2(J(w,nu)+J(c,omega)), for every actual v,w,c. For arbitrary actual a,b in E and mu in Real with q(a)=mu I, the application derives q(D(a,b))=0 under DenseRange q. Density is absent from the signed-semidefinite second-image step and the second actual-table identity; it is retained for arbitrary-second Jordan orthogonality, spectral confinement and the final conclusion.")),
                    Paragraph(Text("These are hypotheses on an arbitrary q, independent of ActualMatrixCorner. They require neither a closed original Peirce corner, closure of that corner under D, a norm-preserving matrix equivalence, injectivity of q nor completeness of E. In particular a need not equal mu u in E. All response arguments below are actual original labels, including inner D tails. Equal q images do not authorize exchanging labels inside D; no response on q(E), quotient or pointwise image is defined. No additivity, homogeneity, continuity, measurability, locality or descent of D is assumed.")),
                    Paragraph(Text("Let V=EuclideanSpace Complex n with real inner product <v,w>=Re inner_Complex(v,w), and let Q_e be the ordinary action of q(e) on V. Matrix.toEuclideanCLM gives this action and is injective as a map of matrices; this uses no injectivity of q. Self-adjointness makes every Q_e symmetric. Real linearity, the unit and Jordan hypotheses give a whole-domain PBActualOuterBudget.Readout J u D top with op(e)=Q_e. For each vector v, f_v(e)=<v,Q_e v> is real linear and nonnegative on C, by Matrix.isPositive_toEuclideanLin_iff. Apply the existing positive_table_transfer, equivalently the first clause of original_positive_readings, with the exact substitutions C={e:0<=i(e)}, p=O.preparation, hexact=O.exact_cone and hraw=O.raw_p2. It supplies the entire Hermitian directed table and f_v(D(r,s)) squared <= f_v(J(r,r)) f_v(J(s,s))-f_v(J(r,s)) squared for every actual r,s.")),
                    Paragraph(Text("The existing PBActualOuterBudget.reading_jordan identifies f_v(J(r,s))=<Q_r v,Q_s v>. Therefore every actual pair has the real Gram bound <v,Q_D(r,s) v> squared <= norm(Q_r v) squared norm(Q_s v) squared-<Q_r v,Q_s v> squared. If Q_s v=k Q_r v for real k, the right side is zero and that one response reading vanishes. Taking s=k r for all v and applying LinearMap.IsSymmetric.inner_map_self_eq_zero gives q(D(r,k r))=0. If q(s)=0 the same argument at k=0 gives q(D(r,s))=0 for any actual r, without identifying s with zero. Hermitian off-diagonal equality in the transferred originalTable gives f_v(D(s,r))=-f_v(D(r,s)); symmetric polarization and injective matrix action give q(D(s,r))=-q(D(r,s)). Consequently either zero input image annihilates the response image. In particular mu=0 already gives the final conclusion, without density. These mathematical vector functionals add no preparations and divide by no preparation mass.")),
                    Paragraph(Text("Put H=D(a,b), h=q(H) and B=q(b); use the same letters for their actions. First suppose B or -B is positive semidefinite. If h were nonzero, Matrix.IsHermitian.exists_eigenvector_of_ne_zero supplies v nonzero and real Z nonzero with hv=Zv. Set k=Z/(1+mu squared), c=k a, nu=H-J(a,c), omega=J(a,b)+D(a,c). Proportional-pair P2 gives only q(D(a,c))=0 for this calculation. Jordan compatibility gives q(J(a,c))=k mu squared I and q(omega)=mu B. Thus the literal PB(a,b,c) outer labels r_plus=b+nu, s_plus=c+omega, r_minus=b-nu, s_minus=c-omega have images R_plus=B+h-k mu squared I, S_plus=k mu I+mu B, R_minus=B-h+k mu squared I and S_minus=k mu I-mu B. On this v, S_plus v=mu R_plus v and S_minus v=-mu R_minus v. The two actual outer response readings vanish by their own Gram bounds.")),
                    Paragraph(Text("The image of that PB right side is -2(B circle (h-k mu squared I)+(k mu I) circle (mu B))=-2 B circle h, where M circle N=(MN+NM)/2. On the eigenvector its reading gives Z<v,Bv>=0. Hence <v,Bv>=0. Hermitian reality and Matrix.PosSemidef.dotProduct_mulVec_zero_iff, applied to B or to -B, give Bv=0 in either sign case. P2 at the original pair (a,b) then has zero second action vector and forces <v,hv>=Z norm(v) squared=0, a contradiction. This proves signed-semidefinite second-image absorption without density or square lifts, for positive, zero and negative mu. If the target is zero the conclusion is immediate; no nonzero eigenvector is requested in that branch.")),
                    Paragraph(Text("For arbitrary B now retain DenseRange q. The real vector space of self-adjoint matrices is finite dimensional, using FiniteDimensional.of_injective on its inclusion into all matrices. The range of the real-linear q is a finite-dimensional subspace and is closed by Submodule.closed_of_finiteDimensional. Density therefore makes q surjective, without continuity of q or completeness of E. Given any positive semidefinite matrix M, choose actual e in E with q(e)=CFC.sqrt M. The suppliers CFC.sqrt_nonneg and CFC.sqrt_mul_sqrt_self, together with Jordan compatibility, give q(J(e,e))=M. For negative semidefinite C, lift -C this way and take c=-J(e,e); for positive semidefinite C take c=J(e,e). These are actual signed original squares. They do not postulate original spectral projections, roots or inverses.")),
                    Paragraph(Text("If h=0 there is nothing to prove about q(J(b,H)). Otherwise symmetric polarization supplies a vector w with <w,hw> nonzero. In the remaining mu nonzero branch, fix any v with <v,hv> nonzero and put tau=mu/(1+mu squared), W=tau hv and r=<v,W>. Then r is real and nonzero. The complex rank-one operator M:z maps to inner_Complex(W,z) W is positive by InnerProductSpace.isPositive_rankOne_self. Let C=M/r. Its sign is semidefinite according to the sign of r. The preceding signed-square lift gives an actual c with q(c)=C, and semidefinite absorption gives q(D(a,c))=0. Self-adjointness of h makes inner_Complex(W,v)=r, with zero imaginary part, so InnerProductSpace.rankOne_apply gives Cv=W and (1+mu squared)Cv=mu hv.")),
                    Paragraph(Text("For this c keep nu=H-J(a,c), omega=J(a,b)+D(a,c) in literal PB(a,b,c), with the same four original outer labels b+nu,c+omega,b-nu,c-omega. Their action vectors on v again obey Q_(c+omega)v=mu Q_(b+nu)v and Q_(c-omega)v=-mu Q_(b-nu)v. Two P2 instances kill both outer readings. The right side reduces to -2<Bv,hv>, since the terms mu<Bv,Cv> and mu<Cv,Bv> cancel. Thus <v,q(J(b,H))v>=<Bv,hv>=0 whenever <v,hv> is nonzero. This computation uses the already derived image of D(a,c), and retains D(a,c) in each original outer argument.")),
                    Paragraph(Text("To include every zero reading of h, fix the same known matrices h and T=q(J(b,H)) and a w with <w,hw> nonzero. For arbitrary v define real polynomials f(t)=<v+t w,h(v+t w)> and g(t)=<v+t w,T(v+t w)>. Their coefficients are respectively the constant reading at v, the cross term <v,hw>+<w,hv>, and the leading reading at w, with the analogous three coefficients for T. At every real t, either f(t)=0 or the preceding PB calculation gives g(t)=0. Hence Polynomial.funext gives f*g=0. The coefficient of degree two of f is nonzero, so f is not the zero polynomial; the integral-domain law gives g=0. Its constant coefficient is <v,Tv>=0. Symmetric polarization now gives T=0, equivalently Bh+hB=0. This is an algebraic extension of fixed quadratic readings, with no limit of unknown D outputs. The h=0 and mu=0 branches were settled before choosing w or dividing by r.")),
                    Paragraph(Text("The second fixed table requires no density. Call literal PB(b,a,mu b) and define exactly nu_2=D(b,a)-J(b,mu b), omega_2=J(b,a)+D(b,mu b), x=a+nu_2, y=mu b+omega_2, x_minus=a-nu_2 and y_minus=mu b-omega_2. Transferred directed-table skewness gives q(D(b,a))=-h; proportional-pair P2 gives q(D(b,mu b))=0. The Jordan law gives q(J(b,a))=mu B and q(J(b,mu b))=mu B squared. It follows that X=q(x)=mu(I-B squared)-h, Y=q(y)=2mu B, and q(y_minus)=0. The last equality concerns only the image of that actual label; y_minus is not replaced by the original zero in D(x_minus,y_minus). Zero-second-image P2 gives q(D(x_minus,y_minus))=0.")),
                    Paragraph(Text("The same PB right side has image -2(mu(-h-mu B squared)+mu squared B squared)=2mu h. Thus q(D(x,y))=2mu h, with all parentheses, signs and argument order inherited from PB(b,a,mu b). The two fixed actual P2 tables are therefore (mu I,B,h) from (a,b), and (X,Y,2mu h) from (x,y). They are triples of images of original calls, not the values of a new image-level response. In particular no closure or descent premise on D has supplied the second table.")),
                    Paragraph(Text("Return to the dense case and Bh=-hB. The real symmetric actions B squared and h commute. Apply the pinned Mathlib theorem LinearMap.IsSymmetric.iSup_iSup_eigenspace_inf_eigenspace_eq_top_of_commute to B squared and h; their common eigenspaces span V. On such a space write B squared v=t v and hv=zv. A zero v or z=0 already satisfies (t-1)zv=0. Otherwise normalize v to norm one. Symmetry and anticommutation give <v,Bv>=0, norm(Bv) squared=t and hBv=-zBv. First-table P2 reads z squared <= mu squared t, so t>0 and mu is nonzero. With r=sqrt(t) and w=Bv/r, the vectors v,w are orthonormal and Bv=rw, Bw=rv, hv=zv, hw=-zw. Zero t is thus excluded only in this nonzero-z branch.")),
                    Paragraph(Text("For arbitrary real c,s read the second actual table at u_0=cv+sw. Its known action vectors are X u_0=(mu(1-t)-z)c v+(mu(1-t)+z)s w and Y u_0=2mu r(sv+cw); the response reading is 2mu z(c squared-s squared). Their Gram determinant is (2mu r) squared times [mu(1-t)(c squared-s squared)-z(c squared+s squared)] squared. Cancel the strictly positive factor (2mu) squared in P2. For each eta in [-1,1] choose c=sqrt((1+eta)/2) and s=sqrt((1-eta)/2), using Real.sqrt_pos and Real.sq_sqrt where appropriate. The result is (z eta) squared <= t[mu(1-t)eta-z] squared for every eta in this entire interval, together with z squared <= mu squared t from the first table.")),
                    Paragraph(Text("Here is the complete scalar exclusion. Sign changes of eta and invariance of squares reduce mu,z to m=abs(mu)>0 and Z=abs(z)>0. Suppose t differs from one and set C_0=m abs(1-t)>0. Choosing eta or -eta according to the sign of 1-t gives (Z eta) squared <= t(C_0 eta-Z) squared for all eta in [0,1]. If Z<=C_0, the admissible eta=Z/C_0 makes the right side zero while its left side is positive, a contradiction. Hence C_0<Z. Put r=sqrt(t)>0. The first bound gives Z<=mr; the endpoint eta=1 gives Z<=r(Z-C_0). This forces r>1, since otherwise r(Z-C_0)<Z. Rearranging gives r C_0<=(r-1)Z<=m r(r-1), hence C_0<=m(r-1). Now t=r squared>1, so C_0=m(t-1), and cancellation of m gives t<=r. This contradicts r squared=t and r>1. Thus (t-1)z=0 in every common eigenspace, including the earlier zero-z case. The spanning theorem gives (B squared-I)h=0 on all V and, by injective matrix action, as a matrix equality. Repeated eigenvalues and the empty space require no special basis choice.")),
                    Paragraph(Text("For the final step mu=0 has already been paid by zero-image P2; retain mu nonzero and the very same actual x,y from the second table. Set d=D(y,x) and g=J(y,x). Skewness gives q(d)=-2mu h. Expanding only the known Jordan multiplication of X and Y, using Bh+hB=0, gives G=q(g)=2mu squared(B-B cubed). The spectral relation B squared h=h implies Gh=0; self-adjointness also gives hG=0. It also gives Xh=-h squared. G is generally not zero: its annihilation of h, rather than its vanishing, is the input to the final reading.")),
                    Paragraph(Text("Call literal PB(y,x,0). Its inner labels are nu_3=d-J(y,0) and omega_3=g+D(y,0), and its equality is D(x+nu_3,0+omega_3)-D(x-nu_3,0-omega_3)=-2(J(x,nu_3)+J(0,omega_3)). Bilinearity gives J(y,0)=J(0,omega_3)=0. The zero-second-image consequence of original P2 gives q(D(y,0))=0; this calculation does not substitute D(y,0)=0 into the arguments. In particular q(omega_3)=G, generally nonzero. Both original outer second labels 0+omega_3 and 0-omega_3 remain literal, and both of their matrix actions on hv vanish because Gh=0.")),
                    Paragraph(Text("For every v use the positive mathematical sandwich reading e maps to <hv,q(e)hv>. It is the original cone-positive vector reading at hv, equivalently the pullback of T maps to <v,hThv>; it is not a new actual preparation. P2 at each literal outer pair has zero second action vector, so each unknown output reading is zero independently. Meanwhile q(nu_3)hv=-2mu h squared v and Xhv=-h squared v. The exact PB right side therefore reads -2<Xhv,q(nu_3)hv>=-4mu norm(h squared v) squared. Consequently 0=-4mu norm(h squared v) squared for every v. Cancellation uses only mu nonzero, not its positivity or a preparation mass.")),
                    Paragraph(Text("Symmetry identifies norm(h squared v) squared with <v,h to the fourth power v>. The existing symmetric power and polarization facts, LinearMap.IsSymmetric.pow and LinearMap.IsSymmetric.inner_map_self_eq_zero, give explicitly h to the fourth power=0. Thus norm(h squared v) squared=0, so h squared v=0 for every v; then norm(hv) squared=<v,h squared v>=0 gives hv=0 for every v. Matrix.toEuclideanCLM injectivity returns h=0 as a matrix, and hence q(D(a,b))=0 in the self-adjoint subtype. This derives the finite implication from positive_table_transfer, the stated original PB and q laws, and the identified pinned matrix, polynomial and symmetric-operator suppliers. It introduces no additional theorem declaration or assumption about the unknown response.")),
                    Paragraph(Text("Every finite index type is included, including empty n and its zero matrix target; a zero vector never needs normalization. Zero h, zero B, zero mu, negative mu, either semidefinite sign, zero quadratic readings, zero eigenvalues and repeated eigenvalues retain the branches above. Only known nonzero quantities are divided: 1+mu squared is always positive, r=<v,W> is used only when nonzero, and sqrt(t) and mu are cancelled only after their nonzero branches. Noninjective q and incomplete E remain allowed. The result is an image statement for the same original D, and supplies no general response invariance along fibers of q.")),
                    Paragraph(Text("Applying this conditional finite result to a continuous matrix bundle still requires a full original-domain OriginalData instance and the actual evaluation maps with their unit, Jordan, original-cone positivity and dense-range proofs on that domain. A constructed ActualMatrixCorner is neither required by this finite argument nor supplied by it. The general JB original-unit-row problem retains its separate approximation obligations. The continuous-bundle realization, original65.2 central zero rows and phase conclusion, and the physical interface remain open. No additional physical operation, preparation availability, empirical response law or completed reconstruction is asserted."))
                )),
                Paragraph(Text("Consider the full C-star algebra M of continuous sections of a locally trivial complex matrix-algebra bundle over a nonempty compact Hausdorff space, with fixed finite fiber size n at least three, and E=M_sa. Retain the same total original D:E times E->E, the exact original cone, every original real-linear evaluation and both orders of every positive directed two-table. Retain PB for every actual triple. No additivity, homogeneity, input continuity, measurability, central translation, locality or quotient descent of D is assumed. Mathematical positive functionals need not be original preparations and may have zero or unnormalized mass.")),
                Paragraph(Text("Let Q be the common continuous central self-adjoint involution and put J=iQ. All products below are the actual associative products in M. For a,b in E put K(a,b)=J(ab-ba)/2. For every Z in M define x(Z)=(Z+Z*)/2 and y(Z)=-J(Z-Z*)/2, so Z=x(Z)+Jy(Z). Set F(Z)=D(x(Z),y(Z))-K(x(Z),y(Z)). Expanding only the known multiplication gives q_D(Z)=x(Z)^2+y(Z)^2+2D(x(Z),y(Z))=star(Z)Z+2F(Z). These definitions keep the old response on its original self-adjoint carrier.")),
                Paragraph(Text("Fix any actual W in M, any self-adjoint s in M and every finite real t>m=norm(s). Put a=Q(tu+s), B=(u-Ja)^(-1)=(u-i(tu+s))^(-1), Z=BW=b+Jd, and U=(u+Ja)B. Define the two actual inner errors e=D(a,b)-K(a,b), g=D(a,d)-K(a,d), and T=e+Jg. Here b=x(Z) and d=y(Z), and e,g are self-adjoint sections. In particular, an s supported in a local trivialization chart is allowed; W need not be supported there. None of the two calls D(a,b),D(a,d) is split into a central term and another call.")),
                Paragraph(Text("The same actual PB triple (a,b,d) has v=D(a,b)-a circle d, w=a circle b+D(a,d), r_plus=b+v, r_minus=b-v, s_plus=d+w and s_minus=d-w. Expansion of K and the Jordan product, using the centrality of J and J squared=-u, gives v+Jw=JaZ+T. Therefore the literal negative endpoint r_minus+Js_minus is (u-Ja)Z-T=W-T, while the literal positive endpoint r_plus+Js_plus is (u+Ja)Z+T=UW+T. Their sum is 2Z. The order of B and W is fixed throughout.")),
                Paragraph(Text("Write A=Ja, so A*=-A, and V=AZ+T. PB and separation give q_D(Z+V)=q_D(Z-V). The ordinary Gram difference is star(Z+V)(Z+V)-star(Z-V)(Z-V)=2(star(Z)V+star(V)Z)=2(star(Z)T+star(T)Z); the A terms cancel because A is skew-adjoint. Substitution in q_D=Gram+2F gives exactly F(UW+T)-F(W-T)=-(star(Z)T+star(T)Z). Neither unknown outer D call is expanded or replaced by a call on a pointwise-equal representative.")),
                Paragraph(Text("Fix one C-positive real-linear functional phi on E. Apply positive_table_transfer to the two literal pairs (r_plus,s_plus) and (r_minus,s_minus), with the very same phi, to obtain |phi(D(r_plus,s_plus))| at most sqrt(Delta_phi(r_plus,s_plus)) and the corresponding minus inequality. Here Delta_phi(r,s)=phi(r squared)phi(s squared)-phi(r circle s) squared. Apply phi to the PB difference and use the real triangle inequality. The resulting common budget is |phi(-2(b circle v+d circle w))| at most sqrt(Delta_phi(r_plus,s_plus))+sqrt(Delta_phi(r_minus,s_minus)). Both determinants are nonnegative by their own transferred tables. No separately selected optimizers, normalization or nonzero mass is used.")),
                Paragraph(Text("Set c=(sqrt(1+(t-m)^2))^(-1), equivalently c=(1+(t-m)^2)^(-1/2). The spectrum of the actual self-adjoint s lies in [-m,m]. On that same spectrum the scalar function f(lambda)=1-i(t+lambda) is nonzero, and |f(lambda)^(-1)|=(1+(t+lambda)^2)^(-1/2) at most c. Continuous functional calculus identifies B with f(s)^(-1) and gives norm(B) at most c. Thus norm(Z) at most c norm(W). The exact identity U+u=2B gives norm(U+u) at most 2c. The self-adjoint real and J-imaginary parts of Z each have norm at most norm(Z); multiplication by the central involution Q preserves the norm.")),
                Paragraph(Text("The transferred P2 inequality for every point-vector functional bounds the quadratic readings of the same self-adjoint D(a,b) by norm(a)norm(b) times the vector mass. The self-adjoint matrix norm and the supremum section norm therefore give norm(D(a,b)) at most norm(a)norm(b), for every original pair. Since norm(a) at most t+m and norm(b),norm(d) at most c norm(W), both actual D terms are bounded by (t+m)c norm(W). The exact cancellation Q squared=u gives K(a,b)=i[s,b]/2 and K(a,d)=i[s,d]/2. Submultiplicativity bounds these by mc norm(W). Hence norm(e),norm(g) at most (t+2m)c norm(W), and norm(T) at most 2(t+2m)c norm(W). This estimate uses no regularity of D as its inputs vary.")),
                Paragraph(Text("Finally the exact defect difference gives norm(F(UW+T)-F(W-T)) at most norm(star(Z)T)+norm(star(T)Z), hence at most 2 norm(Z)norm(T) and at most 4(t+2m)c squared norm(W) squared. Together with the endpoint sum, these are all the response and inverse-input estimates. For fixed s,W the inverse-input bound tends to zero, whereas the displayed response-error bound is only bounded; it does not force T to vanish.")),
                Paragraph(Text("The support implication requires scalar-first-image absorption for each actual evaluation q_x on the unchanged full original domain. The finite application above supplies the conditional implication q_x(a)=mu I implies q_x(D(a,b))=0 for every actual second label b when that q_x has its stated real-linear, unital, Jordan, original-cone-positive and dense-range properties and the same full OriginalData and PB. Establishing this complete evaluation telescope for the continuous bundle remains an original-domain realization obligation; it is not obtained by descending D to a quotient. At a point with s(x)=0, centrality and the simple matrix fiber give Q(x)=u(x) or -u(x), so a(x)=tQ(x) is scalar. Apply that result separately to the original pairs (a,b) and (a,d). Both inner D values vanish at x; the two commutators also vanish. Therefore e(x)=g(x)=T(x)=0. The nonzero set of T is contained in that of s, and taking closures gives support(T) contained in support(s). Global scalar rows alone do not supply this pointwise premise. The finite conditional argument must be instantiated with the full original-domain evaluation telescope; positive-table transfer and the endpoint calculation alone do not establish that telescope.")),
                Paragraph(Text("All endpoint identities and bounds retain both inner errors. Without an input-regularity statement for the same F, neither the defect bound nor the support inclusion identifies F(W-T) with F(W), and no identity F(UW)=F(W) follows from this argument. These are mathematical consequences on the stated carrier, not claims of additional physical operations, preparation availability or response descent.")),
                Paragraph(Text("This bundle application uses the supplied C-star/full-self-adjoint/OriginalData interface; it does not construct the concrete continuous-matrix-bundle realization or an actual instance. The finite scalar-first-image derivation above supplies its implication under the complete finite evaluation hypotheses; this bundle application still needs those hypotheses instantiated on the full original domain before the support conclusion applies. It establishes neither the unitarity nor the asymptotic assertions.")),
                Paragraph(Text("originalCorner(i,JX,k) is exactly the original inclusion inverse image of the Peirce two-space ker(JX(i(k))-id). Thus its elements are literally original labels in E intersect X two(k). ActualMatrixCorner supplies the source's closed-corner interface: an isometric original inclusion, inherited Jordan multiplication, the original k as corner unit, closure under J and the same D, and a real-linear equivalence onto all self-adjoint complex matrices. The equivalence preserves the inherited norm using the matrix L2 operator norm, the unit, the Jordan product, and the exact inherited cone. This is a conditional interface, not a construction from abstract JB axioms. Density and completeness of a real JB completion are not needed once this actual finite interface is supplied.")),
                Paragraph(Text("cornerJordan and cornerResponse are literal restrictions: their underlying original labels are J(a,b) and D(a,b). Every original evaluation restricts by composition with the original subtype inclusion, so exact-cone detection and all original directed tables restrict without changing preparations or their masses. The matrix equivalence is onto the whole finite self-adjoint matrix space; no proper surrogate matrix subsystem is substituted.")),
                Paragraph(Text("cornerOp is ordinary matrix action on EuclideanSpace over the complex scalars. cornerVectorRead is the real part of the vector expectation, is real linear and nonnegative on the inherited cone, and its complex expectation is real. It reads k as the squared Euclidean norm, J(a,a) as the squared Euclidean norm of a acting on the vector, and J(a,b) as the real inner product of the two resulting vectors. Whole-table transfer and the determinant give the budget on the literal original D(a,b). The index type may be empty and the vector may be zero. The zero corner and k=0 remain in scope whenever the supplied interface exists; no ambient extension, GNS representation or normalized vector is used.")),
                Paragraph(Text("A further application uses arbitrary original labels V and B in the same complex C-star inclusion, a possibly zero projection q, real R and nonnegative epsilon and M. Suppose the geometric input estimates are norm(i(V)q) at most 2 abs(R) epsilon and norm(i(B)) at most M. Set O=D(V,B), without imposing a response law on O. For every positive complex-linear ambient functional omega, the real-linear functional f(a)=Re omega(q i(a) q) is positive on the exact original cone. original_positive_readings therefore gives f(O) squared at most f(J(V,V)) f(J(B,B)) minus f(J(V,B)) squared. Compression of the C-star square bounds gives f(J(V,V)) at most 4 R squared epsilon squared Re omega(q) and f(J(B,B)) at most M squared Re omega(q). Both factors are nonnegative. Thus abs(omega(q i(O) q)) squared is at most 4 R squared epsilon squared M squared (Re omega(q)) squared. Positivity makes the reading of the self-adjoint output real. No reading mass, R or epsilon is divided; zero functionals, q=0, R=0 and the zero algebra remain included.")),
                Paragraph(Text("Write k=2 abs(R) epsilon M. The same estimates give norm(q i(O) q) at most k and the order interval from minus k q to k q. To see the norm conclusion without choosing a faithful or normalized state, apply a norming real functional to the self-adjoint subspace and use CentralPositiveFunctionalExtension.exists_positive_extensions_norm_additive. Its two positive ambient functionals have total unit mass equal to the norm of the real functional. Since q lies between zero and one, the bounds on their q masses sum to at most this unit mass. The resulting inequality bounds the norm by k. Compressing the self-adjoint norm order interval by q gives the asserted interval with q as its unit. This application needs neither a trace nor a response on the completed domain.")),
                Paragraph(Text("For the approximate-window PB network, take x=c+z, a=R h, g=D(a,x), V=T-2 J(a,c), and B=A_minus=x-g-R squared c+J(a,T). Then the preceding budget reads the actual outer output O=D(V,A_minus). Its geometric premises are the localized estimate on V and the bound on A_minus; they are not hypotheses about the unknown output. The PB equation is a separate application: if J(a,z)=0, J(a,J(a,c))=R squared c, J(J(a,c),J(a,c))=R squared J(c,c), J(c,J(a,T))=J(T,J(a,c)), and the original even-label row supplies D(a,T-J(a,c))=0, substitute the literal triple (a,x,T-J(a,c)) in PB. With A_plus=x+g+R squared c-J(a,T), original skew symmetry gives O=D(T,A_plus)-2 J(x,g)-2 R squared J(z,c)+2 J(z,J(a,T)). No additivity, homogeneity or limit of D is used in this substitution.")),
                Paragraph(Text("The positive-reading theorem does not supply that even-label zero row or the reflected frame's actual transverse response. To identify the same O on two approximate windows, the original reflection must supply H and D(H,e) with the same central orientation Q, and the affine projection law must apply to the actual D(T,A_plus). Only then does the rectangle identity read O_ij=i sigma R(a-b) Q X_ij-(c_i X_ij+X_ij c_j), with X_ij=q_i r q_j and the true background compressions c_i,c_j. The small positive-reading budget alone does not identify X_ij. The finite-trace energy identity, all-window sum retaining N-1, fixed-output limit and original residual-elimination criterion are additional obligations for the full spectral conclusion; none is a consequence claimed by original_positive_readings alone."))),
            DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("original-piecewise"),
            DeclarationHandle.Create("D5/S3/Quantum/Algebra/PBOriginalReadoutRealization.original_piecewise"),
            H("Coherent realization with zero and nonzero axis branches"),
            StatementSource.FromAuthor(Disp(Statement())), AssessedProvenance.FromRepo(),
            Blocks(
                Paragraph(Text("OriginalData retains the original real normed label space E, its bilinear Jordan product J, unit u, and arbitrary total response D:E times E to E. Its supplied inclusion i into an arbitrary unital complex C-star algebra A is real linear, isometric and self-adjoint valued, maps u to one, and satisfies i(J(a,b))=(i(a)i(b)+i(b)i(a))/2. E need not be complete or dense in the whole self-adjoint part of A. The original preparation family is arbitrary and its cone is exact: i(a) is positive exactly when every original preparation evaluates a nonnegatively. Every original directed Hermitian two-table is positive semidefinite. No mass is divided or normalized; zero, unequal and subnormalized original masses remain in the domain.")),
                Paragraph(Text("For every vector v in the closed cyclic subspace, vectorRead is the real expectation of the original label in the ambient GNS representation. Positivity of a C-star square makes this a positive functional on the exact original cone. compressed_p2 applies the universal positive-functional clause of original_positive_readings to this functional and takes its determinant bound. The compression inner-product identity identifies that bound with Readout.p2 for every original pair. actual_outer_budget uses this same P2 field at its constructed supporting vector for both actual outer D calls; its finite estimate therefore uses the positive-reading supply. The finite matrix-corner clause is a separate application and is not needed for this C-star compression.")),
                Paragraph(Text("B and C are unital star subalgebras of the same A, C is norm closed, C is contained in B, and every element of C commutes with every element of B. The theorem accepts a specified unital star character chi:C to the complex scalars. Its existence forces this character branch to be proper. Hahn-Banach extends the continuous character functional with its norm preserved. Norm one and value one imply positivity, giving one ambient state phi which retains this chi. The original normalized_gns declaration supplies the norm-one cyclic vector in the completed GNS space. No independent extension is selected for each reading vector.")),
                Paragraph(Text("cyclicSpace(phi,B) is the norm closure of the range of b mapped to pi(b)xi in that one ambient GNS representation. It contains xi and is B invariant. For c in C, retention makes pi(c-chi(c)one)xi have zero squared norm. Centrality propagates this equality along the B orbit and continuity passes it to its closed span, so pi(c)v=chi(c)v for every vector in cyclicSpace. Its real Hilbert space is nontrivial because xi has norm one.")),
                Paragraph(Text("compressedOp sends every original a in E to the orthogonal compression of pi(i(a)) to that single cyclicSpace, regarded as a real linear operator. This map is linear and symmetric on all original labels, including unknown outer D outputs. It reads u as the identity. The known Jordan domain is exactly L=i inverse image of B; invariance proves the Jordan law there. No closure, descent, additivity, homogeneity or extension of D is introduced.")),
                Paragraph(Text("The family of ambient GNS representations over all positive complex-linear functionals separates the original labels, without selecting one faithful state. Suppose pi_f(i(a))=pi_f(i(b)) for every positive f on the same A. Put y=i(a)-i(b), which is self-adjoint. Reading pi_f(y)=0 at the GNS vector represented by the original unit gives f(y)=0, even when f has zero or unnormalized mass. A norming real functional on the self-adjoint subspace is the difference of two positive ambient functionals by CentralPositiveFunctionalExtension.exists_positive_extensions_norm_additive. Its value at y is therefore zero, so the norm of y is zero and the original isometric inclusion gives a=b. This argument also covers the zero algebra and incomplete or nonseparable original E. It supplies a return from identities in every GNS representation; an identity in one selected character realization does not meet this premise.")),
                Paragraph(Text("For the affine first-label projection, the missing response input is the actual scalar-window law D(s u+r h,t p+alpha(u+h))=(r t)q for both original pairs (p,q)=(e,j) and (j,-e), for all four real parameters. In the scalar-window formula D(s u+x,beta u+y)=x cross y, the exact substitution is x=r h, beta=alpha and y=alpha h+t p, with h cross p=q. The source derivation requires the original pure three-axis response, original transverse unit-shift law and original label-rotation invariance; the same D and all finite PB labels must be retained. In its one-PB transport, the still required shifted inner value is D(n,(T u+y-n cross y)/2)=(y+n cross y)/2 for a unit n perpendicular to both pure inputs. These original-response suppliers are not fields proved by OriginalData or by the positive-reading theorem. A classification whose total response has the whole four-dimensional spin factor as codomain cannot be restricted to this window before the original output-closure bridge is proved.")),
                Paragraph(Text("PBAffineFirstBudget.actual_affine_anchor_identity already gives the single-anchor identity when its actual anchor family and whole-domain Readout are supplied. The existing compressedReadout construction, with B equal to the whole ambient algebra, has every original label in its known Jordan domain; its complex compression identities connect this real interface to GNS operators. Its two anchor applications must still be combined through the complex inner product, both central orientation sectors and fixed-operator polarization before the GNS-family separation argument returns the projected equality to E. For a sector Q xi=sigma xi with h xi=-xi, the required quadratic identity is inner(j xi,(g-i r sigma v)xi)=0, with g=D(s u+r h,x) and v=x-J(h,J(h,x)). Polarization must kill the fixed compressed operator on that whole sector, with the reverse block obtained by adjoint and empty sectors included. The zero first-axis coefficient requires the original whole-unit zero row. No general response additivity, first-slot homogeneity, unit translation or continuity follows merely from the readout construction.")),
                Paragraph(Text("For the common-extension step in the original 217–218 argument, fix the same original a,b,d=D(a,b) and let B be the norm closure in A of the unital star algebra generated by i(a),i(b),i(d). Let fB be any positive continuous complex-linear functional on B. Hahn-Banach gives a complex-linear ambient extension g of equal norm. Since the inclusion preserves one and positivity gives norm(fB)=fB(one), the extension satisfies norm(g)=g(one); the positive-functional norm criterion makes g positive. This construction preserves the entire functional and its mass, including zero, without dividing by that mass. The real functional f on the original E is Re(g(i(e))). original_positive_readings applies to this one f at every original pair. Applying the same f to full PB reads both literal outer calls D(b+nu,c+omega) and D(b-nu,c-omega), even when their images lie outside B. Orthogonal compression gives these same expectations on cyclicSpace. Neither the original preparation family nor the response map is extended.")),
                Paragraph(Text("The separate irreducible-family route starts with each pure state of this B. A positive ambient extension need not be pure on A. Its B orbit closure, equipped with the restricted ambient operators and the same cyclic vector, must instead be identified with the GNS triplet of the original B state. GNS uniqueness then transfers topological irreducibility to this closed cyclic space. The family of all pure B states separates B; applying the original isometric inclusion returns any vanishing original label to E. The required external Lean sources are kencyke/quantum-system at revision 5d67fe8030eaf1bdaf081e2acfcbe3fbaecfda7c, GNS.Representation.isPure_iff_isIrreducible and GNS.DirectSum.pureStateFamily_separatesPoints. These sources are outside this module's canonical import closure. Accordingly original_piecewise certifies the central-character realization stated above, while admission of the additional irreducible-family bridge remains separate. No finite-dimensional, separability or faithful-single-state assumption supplies this step, and the step supplies neither Pauli coordinates nor the original square saturation.")),
                Paragraph(Text("In this same supplied JC carrier, raw directed P2 and the exact cone already imply D(a,r a)=0 for every real r: the transferred determinant is zero on proportional pairs, and the original preparations separate by cone antisymmetry and the isometric inclusion. This includes both zero rows. Suppose now that J(a,b)=0 and d=D(a,b). PB at (a,b,0) has inner labels d and zero, so its two literal outer D values vanish and J(b,d)=0. Hermitian skewness, commutativity of J and the exchanged substitution give J(a,d)=0. The three actual images i(a),i(b),i(d) therefore pairwise anticommute. Each of their squares commutes with every generator and its adjoint. The closed double-centralizer inclusion for the topological star adjoin then makes each square commute with all of B. In every nonnull topologically irreducible representation of this actual B, CStarRep.isIrreducible_iff_centralizer in the same pinned external source makes the three represented squares scalar. Self-adjointness and a unit-vector expectation make those scalars nonnegative real squares. This applies to the actual pure-B cyclic family above and uses no finite dimension, separability, prescribed Pauli labels or purity of the ambient extension. These applications remain outside this module's canonical import closure. They do not supply the local original value D(a,t u+lambda a)=0 needed in actual_outer_budget, its full BDerivedInterface, or the equality between the represented d square and the product of the represented a and b squares.")),
                Paragraph(Text("The same actual cyclic space also retains the degenerate branch without affine-zero input. For an arbitrary vector v, the vector functional of the initial ambient extension reads every original label and its P2 determinant. If either represented original a or b is zero and J(a,b)=0, that determinant forces the diagonal reading of d to vanish for every v. Symmetry then makes the represented d zero. A vanishing square radius X or Y makes its self-adjoint axis zero, so the actual represented difference d squared minus a squared times b squared is zero in this branch. No vector mass is divided in this argument. For the exact return to E, anticommutation makes the represented a and b squares commute, and the original inclusion sends J(d,d)-J(J(a,a),J(b,b)) to i(d) squared minus i(a) squared times i(b) squared. If this same difference vanishes in every member of the actual pure-B cyclic family, its existing separation theorem and the same isometric inclusion return the original difference as zero. This last implication leaves the nonzero-radius premise unpaid; it does not identify the two square scalars or establish original square saturation.")),
                Paragraph(Text("On the nonzero-radius branch of each same actual pure-B cyclic representation, write X=pi(i(a)) and Y=pi(i(b)) with their literal B subtypes. The nonnegative real scalar-square radii r and s already supplied above are strictly positive when nonzero. Self-adjointness and the original anticommutation relation therefore meet PauliMultiplicity.exists_pauli_multiplicity exactly. This theorem constructs a closed nonzero complex subspace K of that actual cyclic Hilbert space and one complex linear isometric equivalence U from the Hilbert product K plus K onto it. For every pair (u,v), U(u,v)=u+pi(i(b))(v)/s, pi(i(a))U(u,v)=U(r u,-r v), and pi(i(b))U(u,v)=U(s v,s u). The inverse of U decomposes every vector of the same representation space. Both radii and both original axes remain matched, and the entire separating pure-B family is retained. The space may be infinite dimensional and nonseparable, and K is complete because it is closed. This application uses the same external irreducible-family sources outside this module's canonical import closure. It does not identify the represented d-square scalar with r squared times s squared, derive the original affine-zero or general unit row, or supply the remaining nonzero PB budget application. The earlier zero-radius and conditional original pullback conclusions retain their stated scope.")),
                Paragraph(Text("For complex coefficients z and w, the original quadratic label is normSq(z)J(a,a)+normSq(w)J(b,b)+2 Re(conjugate(z)w)J(a,b)+2 Im(conjugate(z)w)D(a,b). Hermitian original tables determine the reversed readings. Their positivity and the exact original cone make this label positive in A. Every mathematical positive functional therefore reads the same whole two-table positively. The determinant gives f(D(a,b)) squared at most f(J(a,a))f(J(b,b))-f(J(a,b)) squared. Applying this to the actual ambient vector expectation and then the compression proves Readout.p2 for every pair of original labels and every vector, including zero. Mathematical vector expectations are not identified with original preparations.")),
                Paragraph(Text("SectorCertificate contains six actual elements xx,yy,dd,xy,xd,yd of C, wired respectively to i(J(x,x)), i(J(y,y)), i(J(D(x,y),D(x,y))), i(J(x,y)), i(J(x,D(x,y))) and i(J(y,D(x,y))). It requires the original x,y,D(x,y) to lie in L. The specified character reads the first three as X squared, Y squared and delta squared, and the last three as zero. Scalarization and the local Jordan law prove the represented square and anticommutation relations. Global ambient anticommutation is not a premise: the three central cross elements may be nonzero globally.")),
                Paragraph(Text("When X=0 or Y=0, raw all-vector P2 forces every diagonal expectation of op(D(x,y)) to vanish. Symmetry makes that operator zero, and its represented square on the nontrivial cyclic space gives delta=0. This branch uses no involutions. When X and Y are both nonzero, normalize only the mathematical represented axes by real scalars to construct Fibre of the same Readout. X and Y may be unequal and delta may be zero. This normalization supplies no new original input, physical inverse or operation.")),
                Paragraph(Text("The nonzero branch directly applies PBActualOuterBudget.actual_outer_budget to this constructed R and Fibre, the same original J,u,D,x,y, original PB and the complete six-field BDerivedInterface. For every real lambda,t with t nonzero and t squared=lambda squared X squared+1, write z=t u+lambda x, nu=D(x,y)-J(x,z), omega=J(x,y)+D(x,z). It obtains one unit vector reading both actual outer original labels D(y+nu,z+omega) and D(y-nu,z-omega), each with squared budget X squared/t squared+delta squared, their difference 2 lambda X squared Y/t, and lambda squared X squared(X squared Y squared-delta squared) at most X squared+delta squared. Omega may be globally nonzero; only its operator reading is killed. Unknown outer D outputs remain original labels and need not belong to L.")),
                Paragraph(Text("For the zero algebra A, faithfulness makes every original label and every original D value zero, independently of a character or normalized state. This is the first conjunct of the theorem. The second conjunct constructs the specified-character realization whenever its premises are supplied.")),
                Paragraph(Text("The realization theorem assumes a supplied complex C-star carrier, SectorCertificate and the six-field BDerivedInterface. It does not construct that carrier from an abstract real JB algebra, exclude Albert factors, derive the certificate or interface from original PB or orthogonality, or prove global response reconstruction or saturation. A single specified-character realization is not asserted faithful; the family separation argument above uses all positive ambient GNS representations. The positive-reading theorem needs only the exact original cone and the original directed two-tables; its stated matrix-corner clause additionally assumes ActualMatrixCorner. The separate finite full-matrix application in the positive-readings commentary uses its explicitly stated q and PB hypotheses. Neither theorem constructs the real JB completion or the actual closed original-response corner from the original axioms."))),
            DescribeRole.Theorem))));

    private static Formula I(string s) => F.Id(s);
    private static Formula C(string s, params Formula[] a) => global::StrataLint.Scribe.DefinitionDsl.Call(s,a);
    private static Formula N(int n) => global::StrataLint.Scribe.DefinitionDsl.Num(n);
    private static Formula All(string s, Formula t, Formula b) => new Formula.Bind(FormulaQuantifier.ForAll,FormulaIdentifier.Create(s),t,b);
    private static Formula Eq(Formula a, Formula b) => global::StrataLint.Scribe.DefinitionDsl.Equal(a,b);
    private static Formula And(Formula a, Formula b) => new Formula.Logic(a,FormulaLogicOperator.And,b);
    private static Formula Imp(Formula a, Formula b) => new Formula.Logic(a,FormulaLogicOperator.Implies,b);
    private static Formula Mul(Formula a, Formula b) => global::StrataLint.Scribe.DefinitionDsl.Multiply(a,b);
    private static Formula Inst(Formula a, Formula b) => Seq(OpenBracket,a,CloseBracket,b);
    private static Formula PositiveStatement()
    {
        var E=I("E"); var P=I("P"); var J=I("J"); var D=I("D"); var cone=I("C"); var p=I("p");
        var f=I("f"); var a=I("a"); var b=I("b"); var X=I("X"); var i=I("i"); var JX=I("JX");
        var k=I("k"); var n=I("n"); var R=I("R"); var v=I("v"); var real=C("Real"); var complex=C("Complex");
        var K=C("originalCorner",i,JX,k); var F=C("cornerVectorRead",R,v);
        Formula Apply(Formula x)=>C("apply",F,x);
        Formula Op(Formula x)=>C("apply",C("cornerOp",R,x),v);
        Formula Sq(Formula x)=>C("pow",x,N(2));
        Formula Norm(Formula x)=>C("norm",x);
        Formula Re(Formula x)=>C("re",x);
        Formula Inner(Formula x,Formula y)=>C("inner",complex,x,y);
        Formula RJ(Formula x,Formula y)=>C("cornerJordan",R,x,y);
        Formula RD(Formula x,Formula y)=>C("cornerResponse",R,x,y);
        var baseTable=All("f",C("RealLinearMap",E,real),Imp(C("PositiveOn",f,cone),
            All("a",E,All("b",E,And(C("PosSemidef",C("originalTable",J,D,f,a,b)),
                C("Le",Sq(C("apply",f,C("apply",D,a,b))),
                    C("Subtract",Mul(C("apply",f,C("apply",J,a,a)),C("apply",f,C("apply",J,b,b))),
                        Sq(C("apply",f,C("apply",J,a,b))))))))));
        var vectors=And(All("a",K,Imp(C("Member",C("val",a),cone),C("Le",N(0),Apply(a)))),
            And(All("a",K,Eq(Inner(v,Op(a)),C("ofReal",Apply(a)))),
            And(Eq(Apply(C("CornerUnit",R)),Sq(Norm(v))),
            And(All("a",K,Eq(Apply(RJ(a,a)),Sq(Norm(Op(a))))),
            And(All("a",K,All("b",K,Eq(Apply(RJ(a,b)),Re(Inner(Op(a),Op(b)))))),
                All("a",K,All("b",K,
                    And(Eq(C("val",RJ(a,b)),C("apply",J,C("val",a),C("val",b))),
                    And(Eq(C("val",RD(a,b)),C("apply",D,C("val",a),C("val",b))),
                    And(C("PosSemidef",C("originalTable",C("cornerJordan",R),C("cornerResponse",R),F,a,b)),
                        C("Le",Sq(Apply(RD(a,b))),C("Subtract",Mul(Sq(Norm(Op(a))),Sq(Norm(Op(b)))),
                            Sq(Re(Inner(Op(a),Op(b))))))))))))))));
        var corners=All("X",I("Type"),Inst(C("NormedAddCommGroup",X),Inst(C("NormedSpace",real,X),
            All("i",C("RealLinearIsometry",E,X),All("JX",C("RealBilinearMap",X,X,X),
            All("k",E,All("n",I("Type"),Inst(C("Fintype",n),Inst(C("DecidableEq",n),
            All("R",C("ActualMatrixCorner",J,D,cone,i,JX,k,n),All("v",C("EuclideanSpace",complex,n),vectors)))))))))));
        var hypotheses=And(C("ExactCone",cone,p),C("AllOriginalTablesPositive",J,D,p));
        var body=All("J",C("RealBilinearMap",E,E,E),All("D",C("Function",E,E,E),
            All("C",C("Set",E),All("p",C("Function",P,C("RealLinearMap",E,real)),
                Imp(hypotheses,And(baseTable,corners))))));
        return All("E",I("Type"),All("P",I("Type"),
            Inst(C("NormedAddCommGroup",E),Inst(C("NormedSpace",real,E),body))));
    }
    private static Formula Statement()
    {
        var A=I("A"); var E=I("E"); var P=I("P"); var O=I("O"); var B=I("B"); var center=I("C");
        var chi=I("chi"); var x=I("x"); var y=I("y"); var X=I("X"); var Y=I("Y"); var delta=I("delta");
        var real=C("Real"); var complex=C("Complex");
        var zero=Imp(C("Subsingleton",A),And(All("a",E,Eq(I("a"),N(0))),
            All("a",E,All("b",E,Eq(C("D",O,I("a"),I("b")),N(0))))));
        var proper=All("chi",C("StarCharacter",center,complex),All("x",E,All("y",E,
            All("X",real,All("Y",real,All("delta",real,
                Imp(C("SectorCertificate",O,B,center,chi,x,y,X,Y,delta),
                    C("Nonempty",C("Realization",O,B,center,chi,x,y,X,Y,delta)))))))));
        var central=All("c",center,All("b",B,Eq(Mul(C("val",I("c")),C("val",I("b"))),
            Mul(C("val",I("b")),C("val",I("c"))))));
        var assumptions=And(C("PB",C("J",O),C("D",O)),And(C("BDerivedInterface",C("J",O),C("u",O),C("D",O)),
            And(C("Closed",center),And(C("Included",center,B),central))));
        var body=All("O",C("OriginalData",A,E,P),All("B",C("StarSubalgebra",complex,A),
            All("C",C("StarSubalgebra",complex,A),Imp(assumptions,And(zero,proper)))));
        body=Inst(C("CstarAlgebra",A),Inst(C("PartialOrder",A),Inst(C("StarOrderedRing",A),
            Inst(C("NormedAddCommGroup",E),Inst(C("NormedSpace",real,E),body)))));
        return All("A",I("Type"),All("E",I("Type"),All("P",I("Type"),body)));
    }
}
